import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.vLhlLNVn.js";const k=JSON.parse('{"title":"SDK Publishing (NPM & PyPI)","description":"Build, verify in isolated consumers, synchronize versions, and publish @jetpack/client (NPM) and jetpack-sdk (PyPI).","frontmatter":{"description":"Build, verify in isolated consumers, synchronize versions, and publish @jetpack/client (NPM) and jetpack-sdk (PyPI)."},"headers":[],"relativePath":"publishing/sdk-publishing.md","filePath":"publishing/sdk-publishing.md","lastUpdated":1795762541000}'),o={name:"publishing/sdk-publishing.md"};function d(c,e,n,l,p,r){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="sdk-publishing-npm-pypi" tabindex="-1">SDK Publishing (NPM &amp; PyPI) <a class="header-anchor" href="#sdk-publishing-npm-pypi" aria-label="Permalink to &quot;SDK Publishing (NPM &amp; PyPI)&quot;">​</a></h1><p>Maintainers can build, verify in clean isolated environments, synchronize versions, and publish both official JetPack SDKs using repeatable user-space <code>Makefile</code> commands:</p><ul><li><strong>Frontend SDK (<code>@jetpack/client</code>)</strong> — <code>web/packages/jetpack-client</code>, bundling compiled <code>jetpack-wasm</code> (<code>crates/jetpack-wasm</code>) into <code>wasm/</code> and re-exporting it via <code>@jetpack/client/wasm</code> so external consumers require zero manual WASM path setup.</li><li><strong>Python Worker SDK (<code>jetpack-sdk</code>)</strong> — <code>sdks/python</code>, built with <code>hatchling</code> (<code>sdist</code> + <code>py3-none-any</code> wheel) with zero mandatory dependencies (<code>dependencies = []</code>) and optional <code>msgpack</code> acceleration (<code>jetpack-sdk[msgpack]</code>).</li></ul><p>See <a href="/sdk/frontend/quickstart">Frontend Quickstart</a> and <a href="/sdk/worker/python-sdk">Python Worker SDK</a> for consumer usage.</p><h2 id="_1-build-both-sdks-make-sdk-build" tabindex="-1">1. Build Both SDKs (<code>make sdk-build</code>) <a class="header-anchor" href="#_1-build-both-sdks-make-sdk-build" aria-label="Permalink to &quot;1. Build Both SDKs (`make sdk-build`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk-build</span></span></code></pre></div><p><code>make sdk-build</code> executes in user space:</p><ol><li>Compiles <code>crates/jetpack-wasm</code> via <code>wasm-pack --target web</code> (<code>make wasm</code>).</li><li>Copies compiled WASM glue and binaries (<code>jetpack_wasm.js</code>, <code>jetpack_wasm.d.ts</code>, <code>jetpack_wasm_bg.wasm</code>, <code>jetpack_wasm_bg.wasm.d.ts</code>) into <code>web/packages/jetpack-client/wasm/</code> and compiles TypeScript to <code>dist/</code>.</li><li>Cleans <code>sdks/python/dist/</code> and builds fresh <code>.tar.gz</code> (<code>sdist</code>) and <code>.whl</code> (<code>wheel</code>) packages via <code>uv build --directory sdks/python</code> (or <code>python3 -m build</code>).</li></ol><h2 id="_2-verify-packaging-isolated-consumers-make-sdk-check" tabindex="-1">2. Verify Packaging &amp; Isolated Consumers (<code>make sdk-check</code>) <a class="header-anchor" href="#_2-verify-packaging-isolated-consumers-make-sdk-check" aria-label="Permalink to &quot;2. Verify Packaging &amp; Isolated Consumers (`make sdk-check`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk-check</span></span></code></pre></div><p><code>make sdk-check</code> runs <code>make sdk-build</code> and executes <code>scripts/sdk_check.sh</code>, verifying:</p><ol><li><strong>Version Parity</strong>: <code>@jetpack/client</code> (<code>package.json</code>), <code>jetpack-sdk</code> (<code>pyproject.toml</code> PEP 440), and <code>EMBEDDED_JETPACK_SDK_VERSION</code> (<code>crates/jetpack-daemon/src/python.rs</code>) match.</li><li><strong>TypeScript SDK Unit Tests &amp; Tarball Inspection</strong>: Runs <code>npm --prefix web/packages/jetpack-client test</code>, packs the <code>.tgz</code>, and verifies <code>dist/</code>, <code>wasm/</code>, <code>README.md</code>, and <code>LICENSE</code> are present without leaking <code>src/</code>, <code>tests/</code>, or <code>node_modules/</code>.</li><li><strong>Isolated Vite + TypeScript Consumer Smoke Check</strong>: Installs the packed <code>.tgz</code> into a fresh temporary Vite + TypeScript project, verifies <code>tsc --noEmit</code> and <code>vite build</code> emit <code>jetpack_wasm_bg-*.wasm</code> into <code>dist/assets/</code>, and confirms <code>vite dev</code> serves <code>/node_modules/@jetpack/client/wasm/jetpack_wasm_bg.wasm</code> with <code>200 OK</code> and <code>application/wasm</code>.</li><li><strong>Python Metadata &amp; Isolated Venv Check</strong>: Runs <code>twine check sdks/python/dist/*</code>, inspects <code>.whl</code> contents (including <code>jetpack_sdk/py.typed</code>), installs the wheel into a clean temporary <code>uv venv</code> without host site-packages, and passes <code>sdks/python/tests</code>.</li></ol><h2 id="_3-version-synchronization-scripts-sync-version-sh" tabindex="-1">3. Version Synchronization (<code>scripts/sync_version.sh</code>) <a class="header-anchor" href="#_3-version-synchronization-scripts-sync-version-sh" aria-label="Permalink to &quot;3. Version Synchronization (`scripts/sync_version.sh`)&quot;">​</a></h2><p>Before tagging a release, synchronize all workspace and SDK manifests from a single semantic version or tag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sync_version.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span></code></pre></div><p>This updates <code>Cargo.toml</code>, <code>crates/jetpack-daemon/assets/Info.plist</code>, <code>web/package.json</code>, <code>web/packages/jetpack-client/package.json</code>, <code>sdks/python/pyproject.toml</code> (converting SemVer pre-release tags such as <code>-alpha.1</code> to PEP 440 <code>a1</code>), and <code>EMBEDDED_JETPACK_SDK_VERSION</code> in <code>crates/jetpack-daemon/src/python.rs</code>.</p><h2 id="_4-dry-run-live-publishing-make-sdk-publish" tabindex="-1">4. Dry-Run &amp; Live Publishing (<code>make sdk-publish</code>) <a class="header-anchor" href="#_4-dry-run-live-publishing-make-sdk-publish" aria-label="Permalink to &quot;4. Dry-Run &amp; Live Publishing (`make sdk-publish`)&quot;">​</a></h2><p>Always run a non-mutating dry run before publishing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk-publish</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DRY_RUN=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p><code>DRY_RUN=1</code> validates the full <code>make sdk-check</code> suite, runs <code>npm publish ./web/packages/jetpack-client --access public --dry-run</code>, checks <code>sdks/python/dist/*</code> with <code>twine check</code>, and skips live uploads (even on a dirty git tree).</p><p>When publishing live from a clean git working tree:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Target Registry</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>make sdk-publish</code></td><td style="text-align:left;">NPM + PyPI</td><td style="text-align:left;">Fails if git tree is dirty unless <code>ALLOW_DIRTY=1</code> is set</td></tr><tr><td style="text-align:left;"><code>make sdk-publish-npm</code></td><td style="text-align:left;">NPM only (<code>@jetpack/client</code>)</td><td style="text-align:left;">Runs <code>sdk-check</code> first</td></tr><tr><td style="text-align:left;"><code>make sdk-publish-pypi</code></td><td style="text-align:left;">PyPI only (<code>jetpack-sdk</code>)</td><td style="text-align:left;">Runs <code>sdk-check</code> first</td></tr></tbody></table><h3 id="authentication-options" tabindex="-1">Authentication Options <a class="header-anchor" href="#authentication-options" aria-label="Permalink to &quot;Authentication Options&quot;">​</a></h3><ul><li><strong>NPM (<code>@jetpack/client</code>)</strong>: Set <code>NPM_TOKEN</code> (or <code>NODE_AUTH_TOKEN</code>)—written to an ephemeral <code>0600</code> temporary config deleted on exit without modifying <code>~/.npmrc</code>—or log in beforehand via <code>npm login</code>.</li><li><strong>PyPI (<code>jetpack-sdk</code>)</strong>: Set <code>UV_PUBLISH_TOKEN</code> (or <code>PYPI_API_TOKEN</code> / <code>TWINE_PASSWORD</code>), or rely on <code>~/.pypirc</code> / an interactive prompt.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Non-interactive CI / token-based publish</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NPM_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> UV_PUBLISH_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk-publish</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Allow publishing while testing uncommitted local edits (not recommended for releases)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ALLOW_DIRTY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk-publish-npm</span></span></code></pre></div><h2 id="_5-github-actions-release-integration" tabindex="-1">5. GitHub Actions Release Integration <a class="header-anchor" href="#_5-github-actions-release-integration" aria-label="Permalink to &quot;5. GitHub Actions Release Integration&quot;">​</a></h2><p><code>.github/workflows/release.yml</code> runs <code>sdk-check</code> on every tag (<code>v*</code>) or manual <code>workflow_dispatch</code> run, gating public desktop releases on SDK packaging verification. When <code>NPM_TOKEN</code> and/or <code>PYPI_API_TOKEN</code> repository secrets are configured, the <code>publish-sdks</code> job publishes both packages automatically after release artifacts succeed; if either secret is omitted, the step logs an informational notice and skips cleanly without failing binary or GitHub Pages releases.</p><p>See also <a href="/publishing/cli-tools">CLI Tools Reference</a> and <a href="/publishing/store-submission">Store Submission &amp; Catalog Signing</a>.</p>',28)])])}const g=s(o,[["render",d]]);export{k as __pageData,g as default};
